        for int_type in all_integration_types:
            int_type_matches = glob.glob(
                f"test/integrations/**/{int_type}_{f}_test.py", recursive=True
            )
            matches.extend(int_type_matches)
        if matches:
            file_targets.extend(matches)
        else:
            remaining_k_filters.append(f)
    # a filter that named no file still selects one through the test class, which is the file
