def retry(retries, integration_name="", reset_timer=False):
    def outer(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            request = kwargs.get("request")
            node = request.node if request else None
            timeout_marker = node.get_closest_marker("timeout") if node else None
            old_timeout = timeout_marker.args[0] if timeout_marker else None

            wrap_retries = retries
            while wrap_retries >= 0:
                try:
                    return func(*args, **kwargs)
                except RetryException as e:
                    if wrap_retries == 0:
                        raise e
                    wrap_retries -= 1
                    time_to_sleep = e.retry_after_seconds + 2
                    msg = f"Sleeping for {time_to_sleep} seconds"
                    if integration_name:
                        msg += f" for {integration_name}"
                    if reset_timer and node:
                        logger.info(f"Clearing timeout for {node.name}")
                        node.cancel_timeout()
                    logger.info(msg)
                    sleep(time_to_sleep)
                    if reset_timer and node and timeout_marker and pytest:
                        node.add_marker(pytest.mark.timeout(old_timeout))
                        logger.info(
                            f"Resetting timeout to {old_timeout} for {node.name}"
                        )

        return wrapper

    return outer


