def get_inventory(self, start, end, first_crawl, first_loop, page_token=None):
    if self.uses_edge():
        return self.get_inventory_from_edge()
    path = "inventory"
    # crawl sftp server, retrieve files and upload to s3
    self.crawl_server()

    # then crawl s3 bucket
    files_from_s3 = self.rjw_request(path)

    # get previously archived files
    archived_files = self.get_archived_files(path)

    # if file is already archived, skip
    for file_name in list(files_from_s3.keys()):
        if file_name in archived_files:
            del files_from_s3[file_name]

    # only archive files that are actually 846s — other transaction
    # sets (944, 997) may land here before routing is deployed
    files_to_archive = []
    inv_items = []
    # rjw's staging server stamps every interchange as test, so on a staging
    # connection that flag is expected and the files are the ones we want
    sandbox = self.integration_secret.get("sandbox") == True
    for file_name, body in files_from_s3.items():
        if detect_edi_resource_type(body) not in (None, "inventory"):
            continue
        files_to_archive.append(f"{path}/{file_name}")
        usage_indicator = edi_usage_indicator(body)
        if usage_indicator and usage_indicator != "P" and not sandbox:
            # rjw drops its onboarding files here too, with segments missing.
            # archived anyway, or it blocks every file that lands after it
            logger.warning(
                f"Skipping non-production RJW interchange {file_name} "
                f"(ISA15 {usage_indicator}) on connection {self.connection_id}"
            )
            continue
        warehouse_sections = edi_846_to_json_with_mapping(body)
        for section in warehouse_sections:
            section["SourceFile"] = file_name
            if not section["Parties"]["IdentificationCode"]:
                # rjw's onboarding files leave the warehouse id off the N1*WH
                # segment. there's no stock to record without it, and stopping
                # here would keep the file from being archived and block every
                # file that lands after it
                logger.warning(
                    f"Skipping RJW 846 section in {file_name} with no warehouse "
                    f"id (warehouse '{section['Parties']['Name']}') on "
                    f"connection {self.connection_id}"
                )
                continue
            date_str = section.get("DateTimeReference", {}).get("Date")
            if not date_str:
                # fall back to BIA date if DTM segment was omitted
                date_str = section.get("BeginningSegment", {}).get("Date")
            if not date_str:
                continue
            section["Date"] = datetime.strptime(date_str, "%Y%m%d").replace(
                tzinfo=pytz.utc
            )
            inv_items.append(section)

    # if more than one file, we want to process them in order of oldest to newest. Newer inventory will overwrite older inventory
    inv_items.sort(key=lambda x: x["Date"])
    inv_items_by_warehouse_id = {}
    formatted_inventory = []
    for inv_obj in inv_items:
        warehouse_id = inv_obj["Parties"]["IdentificationCode"]
        for item in inv_obj["Parties"]["ItemInformation"]:
            item_id = item["VendorItemNumber"]
            if item_id not in inv_items_by_warehouse_id:
                inv_items_by_warehouse_id[item_id] = {warehouse_id: item}
            else:
                inv_items_by_warehouse_id[item_id][warehouse_id] = item

    for item_id, item_by_wh in inv_items_by_warehouse_id.items():
        formatted_item = format_inventory(item_id, item_by_wh)
        formatted_inventory.append(formatted_item)

    return {
        "data": formatted_inventory,
        "next_token": None,
        "file_to_archive": files_to_archive,
    }

