def get_inventory_from_edge(self):
    customer_id = self.edge_customer_id()
    # the stock report says the same thing, but rendering one shows up in the
    # customer's own report history in edge, and these do not
    items = self.edge_request(
        "api/Dashboards/Inventory/inventory-summary",
        params={"customerId": customer_id},
    )
    # an item held at two sites comes back once per site
    items_by_sku = {}
    sku_sequence = []
    for item in items:
        sku = item["itemNumber"]
        if sku not in items_by_sku:
            items_by_sku[sku] = []
            sku_sequence.append(sku)
        items_by_sku[sku].append(item)

    formatted_inventory = []
    for sku in sku_sequence:
        lots = self.edge_request(
            f"api/Dashboards/Inventory/{sku}/lots",
            params={"customerId": customer_id},
        )
        formatted_inventory.append(
            format_inventory_from_edge(sku, items_by_sku[sku], lots)
        )
    return {"data": formatted_inventory, "next_token": None}

def get_products(
    self, start, end, first_crawl, first_loop, page_token=None, sync_job_id=None
):
    # the edi files carry no item descriptions or barcodes, so products are
    # only readable on a connection that has edge credentials
    api_call_path = "edge item detail"
    if not self.uses_edge():
        err = self.create_permissions_exception(api_call_path)
        self.api_call_errors[api_call_path] = err
        raise err
    self.api_call_errors[api_call_path] = None

    customer_id = self.edge_customer_id()
    summary = self.edge_request(
        "api/Dashboards/Inventory/inventory-summary",
        params={"customerId": customer_id},
    )
    formatted_products = []
    seen_skus = []
    for row in summary:
        sku = row["itemNumber"]
        # an item stocked at two facilities is listed once per facility
        if sku in seen_skus:
            continue
        seen_skus.append(sku)
        detail = self.edge_request(
            f"api/Dashboards/Inventory/{sku}", params={"customerId": customer_id}
        )
        formatted_products.append(format_product_from_edge(sku, detail))
    return {"data": formatted_products, "next_token": None}

def get_inbound_shipments_from_edge(self):
    customer_id = self.edge_customer_id()
    # deliveries are few enough to look at all of them each time, which keeps
    # one arriving over two crawls from being counted twice
    window_start = now() - timedelta(days=EDGE_INBOUND_LOOKBACK_DAYS)
    inbounds = self.edge_request(
        "api/Orders",
        params={
            "startDate": window_start.strftime("%Y-%m-%d"),
            "endDate": now().strftime("%Y-%m-%d"),
            "customerId": customer_id,
            "orderType": EDGE_INBOUND_ORDER_TYPE,
        },
