def get_inbound_shipments_from_edge(self):
    customer_id = self.edge_customer_id()
    # deliveries are few enough to look at all of them each time, which keeps
    # one arriving over two crawls from being counted twice
    window_start = now() - timedelta(days=EDGE_INBOUND_LOOKBACK_DAYS)
    inbounds = self.edge_request(
        "api/Orders",
        params={
            "startDate": window_start.strftime("%Y-%m-%d"),
            "endDate": now().strftime("%Y-%m-%d"),
            "customerId": customer_id,
            "orderType": EDGE_INBOUND_ORDER_TYPE,
        },
    )

    po_numbers = []
    for inbound in inbounds:
        if inbound["poNumber"] not in po_numbers:
            po_numbers.append(inbound["poNumber"])
    # edge has no receipts endpoint, so the receipts are worked out from what
    # we already hold against the quantity received now
    existing_by_id = {}
    if po_numbers:
        for stored in InboundShipment(self).batch_get_resources(po_numbers):
            existing_by_id[stored["id"]] = stored

    # several deliveries can land against one po, and they are one shipment
    deliveries_by_po = {}
    po_sequence = []
    for inbound in inbounds:
        po_number = inbound["poNumber"]
        if po_number not in deliveries_by_po:
            deliveries_by_po[po_number] = []
            po_sequence.append(po_number)
        deliveries_by_po[po_number].append(inbound)

    # reading every delivery is cheap, but its lines and lots are a call each,
    # so only go back for the ones that have moved since we last looked
    changed_po_numbers = []
    for po_number in po_sequence:
        existing = existing_by_id.get(po_number)
        if existing and not inbound_changed_on_edge(
            deliveries_by_po[po_number], existing
        ):
            continue
        changed_po_numbers.append(po_number)
    if not changed_po_numbers:
        return {"data": [], "next_token": None}

    # the lines say how much arrived but never which lot, and the only place
    # that says is the stock ledger. it is the whole ledger though, shipments
    # and adjustments included, so only ask across the days these landed
    delivered_dates = []
    for po_number in changed_po_numbers:
        for inbound in deliveries_by_po[po_number]:
            if inbound["deliveredDate"]:
                delivered_dates.append(inbound["deliveredDate"][:10])
    ledger_rows = []
    if delivered_dates:
        ledger_rows = self.edge_report_rows(
            STOCK_ACTIVITY_REPORT_NAME,
            [
                {"name": "CUSTID", "value": customer_id},
                {"name": "IN_BEGDATE", "value": min(delivered_dates)},
                {"name": "IN_ENDDATE", "value": max(delivered_dates)},
            ],
        )
    received_by_order = {}
    for row in ledger_rows:
        if report_text(row["Item Desc"]) != EDGE_RECEIPT_TRANSACTION:
            continue
        # the ledger names the delivery it came from in the description column
        order_number = report_text(row["Trans Desc"])
        if not order_number:
            continue
        if order_number not in received_by_order:
            received_by_order[order_number] = []
        received_by_order[order_number].append(row)

    formatted_inbounds = []
    for po_number in changed_po_numbers:
        deliveries = []
        for inbound in deliveries_by_po[po_number]:
            order_number = inbound["orderNumber"]
            # what was due in and what turned up, per item
            commodities = self.edge_request(
                f"api/Orders/{order_number}/commodities",
                params={"bsid": inbound["orderNumberBusinessSystem"]},
            )
            deliveries.append(
                (inbound, commodities, received_by_order.get(order_number, []))
            )
        formatted_inbounds.append(
            format_inbound_shipment_from_edge(
                po_number, deliveries, existing_by_id.get(po_number)
            )
        )
    return {"data": formatted_inbounds, "next_token": None}

def edge_in_flight_orders(self, customer_id, window_end):
    # once an order ships, edge overwrites its ship date with the time it
    # actually left, so the window above sees it on the day it goes out no
    # matter how late that is. an order still being worked keeps the date it
    # was planned for, and the window walks past that within a day, so ask for
    # those by status as well and they stay in view until they ship
    lookback_start = now() - timedelta(days=EDGE_IN_FLIGHT_LOOKBACK_DAYS)
    in_flight = []
    for status in EDGE_IN_FLIGHT_ORDER_STATUSES:
        rows = self.edge_request(
            "api/Orders",
            params={
                "startDate": lookback_start.strftime("%Y-%m-%d"),
                "endDate": window_end.strftime("%Y-%m-%d"),
                "customerId": customer_id,
                "orderType": EDGE_OUTBOUND_ORDER_TYPE,
                "orderStatus": status,
            },
        )
        in_flight += rows
    return in_flight

