    self.crawl_server()

    files_from_s3 = self.rjw_request(path)
    archived_files = self.get_archived_files(path)
    for file_name in list(files_from_s3.keys()):
        if file_name in archived_files:
            del files_from_s3[file_name]

    file_names = sorted(files_from_s3.keys())
    files_to_archive = [f"{path}/{f}" for f in file_names]

    # rjw's staging server stamps every interchange as test, so on a staging
    # connection that flag is expected and the files are the ones we want
    sandbox = self.integration_secret.get("sandbox") == True
    orders_by_number = {}
    for file_name in file_names:
        content = files_from_s3[file_name]
        usage_indicator = edi_usage_indicator(content)
        if usage_indicator and usage_indicator != "P" and not sandbox:
            # skipped files stay in file_to_archive, so the next crawl that
            # returns real orders archives them and stops re-reading them
            logger.warning(
                f"Skipping non-production RJW interchange {file_name} "
                f"(ISA15 {usage_indicator}) on connection {self.connection_id}"
            )
            continue
        # a 945 file can batch several shipments, so parse yields one entry per order

